!function(){let t=self;t.addEventListener("push",i=>{if(i.data)try{let n=i.data.json(),e={body:n.body,icon:n.icon||"/icon.png",badge:n.badge||"/icon.png",data:n.url||"/",vibrate:[100,50,100],requireInteraction:!0};i.waitUntil(t.registration.showNotification(n.title||"SGD Notification",e))}catch(e){let n={body:i.data.text(),icon:"/icon.png",vibrate:[100,50,100]};i.waitUntil(t.registration.showNotification("SGD Guild Center",n))}}),t.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data||"/";i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t=0;t<i.length;t++){let e=i[t];if(e.url===n&&"focus"in e)return e.focus()}if(t.clients.openWindow)return t.clients.openWindow(n)}))})}();